style.css:
@-moz-document domain("chatgpt.com") {
/* General Background */
    body, .app, .main-container, .sc-ktzZJr, .sc-iuZknt, .sc-bZQynM, .sc-hHyfXX {
        background-color: #fce4ec !important; /* Blush pink background */
        color: #ec9ec0 !important; /* Accent pink text */
    }

    /* Message Containers */
    .chat-container, .message-box, .message, .message-content, .sc-hHyfXX {
        background-color: #f8e3eb !important; /* Light pink background for messages */
        color: #ec9ec0 !important; /* Accent pink text */
    }

    /* Buttons (send, etc.) */
    button, .btn, .send-button, .sc-htpNat, .sc-dxgHYM, .sc-eJkpfF {
        background-color: #ec9ec0 !important; /* Main pink for buttons */
        color: white !important; /* White text for contrast */
        border: none !important;
        border-radius: 5px !important; /* Rounded buttons */
    }

    /* Button Hover Effects */
    button:hover, .btn:hover, .send-button:hover {
        background-color: #d78ba9 !important; /* Slightly darker pink on hover */
    }

    /* Links */
    a {
        color: #ec9ec0 !important; /* Accent pink for links */
    }

    a:hover {
        color: #d78ba9 !important; /* Softer pink on hover */
    }

    /* Input Areas */
    .chat-input, .sc-bZQynM, .sc-llYSJH, .sc-jrQzUz {
        background-color: #fde6ef !important; /* Soft pink input areas */
        color: #ec9ec0 !important; /* Accent pink text */
        border: 1px solid #ec9ec0 !important; /* Accent pink border */
    }

    /* Header and Navbar */
    .header, .sc-hHyfXX, .sc-dxgHYM, .sc-eJkpfF {
        background-color: #fce4ec !important; /* Blush pink header */
        color: #ec9ec0 !important; /* Accent pink text */
    }

    /* Chat Bubbles */
    .bubble {
        background-color: #ec9ec0 !important; /* Pink for sent messages */
        color: white !important; /* White text */
    }

    /* Sidebar */
    .sidebar {
        background-color: #f8e3eb !important; /* Light pink sidebar */
        color: #ec9ec0 !important; /* Pink text in sidebar */
    }

    /* Footer */
    .footer {
        background-color: #f8e3eb !important; /* Light pink footer */
        color: #ec9ec0 !important; /* Pink text in footer */
    }
}
